let DEFAULT_SETTINGS={lat:null,lon:null,theme:"system",language:"system"};export function getSettings(){let t=localStorage.getItem("omegaSettings");if(t)try{return{...DEFAULT_SETTINGS,...JSON.parse(t)}}catch(e){console.error("Failed to parse saved settings:",e)}return DEFAULT_SETTINGS}export function saveSettings(t){localStorage.setItem("omegaSettings",JSON.stringify(t))}